function validate([apple, capacity]) {
  if (apple.length < 1 || apple.length > 50) return 'apple needs 1 to 50 packs.';
  if (capacity.length < 1 || capacity.length > 50) return 'capacity needs 1 to 50 boxes.';
  if (apple.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each pack holds 1 to 50 apples.';
  if (capacity.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each box holds 1 to 50 apples.';
  if (capacity.reduce((a, b) => a + b, 0) < apple.reduce((a, b) => a + b, 0)) return 'All the boxes together must have room for every apple.';
  return null;
}

