function minimumBoxes(apple, capacity) {
  let remaining = 0;
  for (const count of apple) {
    remaining += count;
  }
  capacity.sort((a, b) => b - a);
  let boxes = 0;
  while (remaining > 0) {
    remaining -= capacity[boxes];
    boxes++;
  }
  return boxes;
}

