function minimumBoxes(apple, capacity) {
  // room[c] = most capacity reachable by choosing exactly c boxes (0/1 knapsack on the count).
  const need = apple.reduce((a, b) => a + b, 0);
  const m = capacity.length;
  const room = new Array(m + 1).fill(-1);
  room[0] = 0;
  for (const cap of capacity)
    for (let c = m; c >= 1; c--)
      if (room[c - 1] >= 0) room[c] = Math.max(room[c], room[c - 1] + cap);
  for (let c = 0; c <= m; c++) if (room[c] >= need) return c;
  return -1;
}

