function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    const n = size === 'large' ? int(1, 50) : int(1, 6);
    const m = size === 'large' ? 50 : int(1, 10);
    const top = rand() < 0.5 ? 50 : int(1, 8);
    const apple = Array.from({ length: n }, () => int(1, top));
    const capacity = Array.from({ length: m }, () => int(1, 50));
    const need = apple.reduce((a, b) => a + b, 0);
    if (capacity.reduce((a, b) => a + b, 0) >= need) return [apple, capacity];
  }
}
